select count(1)
from vm_order_package op,vm_order_customer oc
where op.order_code = oc.order_code
and op.tenant_id = #{tenantId}
and oc.ord_status != '3'
and op.delete_flag = '0'
and op.industry_code = #{appCode}

    and op.app_ver_code = #{appVerCode}

